    static List<Edge>[] g;
    static boolean[] vis;

    static long pathSum(int s, int t) {
        vis = new boolean[g.length];
        return dfs(s, t);
    }

    static long dfs(int u, int target) {
        if (u == target) return 0;
        vis[u] = true;
        for (Edge e : g[u]) {
            if (!vis[e.to]) {
                long x = dfs(e.to, target);
                if (x != Long.MIN_VALUE) return e.w + x;
            }
        }
        return Long.MIN_VALUE;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt(), root = fs.nextInt(), m = fs.nextInt();
        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt(), v = fs.nextInt(), w = fs.nextInt();
            g[u].add(new Edge(v, w));
            g[v].add(new Edge(u, w));
        }
        int q = fs.nextInt();
        long answer = 0;
        for (int i = 0; i < q; i++) {
            int type = fs.nextInt();
            int a = fs.nextInt(), b = fs.nextInt();
            if (type == 1) {
                fs.nextInt();
                answer += pathSum(a, b);
            } else {
                int w = fs.nextInt();
                update(g, a, b, w);
            }
        }
        System.out.println(answer);
    }

    static void update(List<Edge>[] g, int a, int b, int w) {
        for (Edge e : g[a]) if (e.to == b) e.w = w;
        for (Edge e : g[b]) if (e.to == a) e.w = w;
    }

    static class FastScanner {
        private final InputStream in; private final byte[] buf = new byte[1 << 16];
        private int ptr=0,len=0;
        FastScanner(InputStream in){this.in=in;}
        int read() throws IOException {
            if(ptr>=len){len=in.read(buf);ptr=0;if(len<0)return -1;}
            return buf[ptr++];
        }
        int nextInt() throws IOException {
            int c, s=1, x=0;
            do c=read(); while(c<=32);
            if(c=='-'){s=-1;c=read();}
            while(c>32){x=x*10+c-'0';c=read();}
            return x*s;
        }
    }
}

