import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] g;
    static int[] mark;
    static int limit, answer;

    static void dfs(int u, int parent, int consecutive) {
        if (mark[u] == 1) consecutive++;
        else consecutive = 0;
        if (consecutive > limit) return;

        boolean leaf = (u != 1);
        for (int v : g[u]) {
            if (v == parent) continue;
            leaf = false;
            dfs(v,u,consecutive);
        }
        if (leaf) answer++;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs=new FastScanner(System.in);
        int n=fs.nextInt();
        limit=fs.nextInt();
        int k=fs.nextInt();
        mark=new int[n+1];
        for(int i=1;i<=n;i++) mark[i]=fs.nextInt();
        g=new ArrayList[n+1];
        for(int i=1;i<=n;i++) g[i]=new ArrayList<>();
        for(int i=0;i<k;i++){
            int u=fs.nextInt(),v=fs.nextInt();
            g[u].add(v);g[v].add(u);
        }
        dfs(1,0,0);
        System.out.println(answer);
    }

